<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { getNarrativeSettings, saveNarrativeSettings } from '../api/client'
const router = useRouter(); const form = reactive({ apiKey: '', enabled: true, baseUrl: '', model: '', maxTokens: 2048 }); const loading = ref(true); const saving = ref(false); const message = ref(''); const error = ref('')
async function load() { try { Object.assign(form, await getNarrativeSettings()) } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法读取模型配置。' } finally { form.enabled = true; loading.value = false } }
async function save() { saving.value = true; message.value = ''; error.value = ''; try { await saveNarrativeSettings({ ...form }); message.value = '配置已保存，下一次模型请求会立即生效。' } catch (cause) { error.value = cause instanceof Error ? cause.message : '配置保存失败。' } finally { saving.value = false } }
onMounted(() => { void load() })
</script>
<template><section class="settings-page page-content"><div class="section-heading"><div><p class="eyebrow">SETTINGS</p><h1>模型配置</h1><p class="lede">AI 是开始游戏的必要条件。配置外部模型后，GM 才能进行初始化提问和叙事。</p></div><button class="quiet-button" type="button" @click="router.push('/')">返回首页</button></div><form class="form-panel settings-panel" @submit.prevent="save"><label class="field wide"><span>API key <em>必填</em></span><input v-model="form.apiKey" type="password" autocomplete="off" placeholder="输入模型服务 API key" /></label><div class="form-grid"><label class="field"><span>Base URL <small>可选</small></span><input v-model="form.baseUrl" placeholder="默认使用现有配置" /></label><label class="field"><span>模型 <small>可选</small></span><input v-model="form.model" placeholder="默认使用现有配置" /></label></div><label class="field wide"><span>输出上限 max_tokens <small>可选</small></span><input v-model.number="form.maxTokens" type="number" min="256" max="65536" step="256" placeholder="默认 2048" /><small>单次响应的输出 token 上限，默认 2048。若出现「模型未完整生成结果（finish_reason=length）」，调大到 4096 或更高。</small></label><p v-if="loading" class="lede">正在读取配置…</p><p v-if="message" class="success-message" role="status">{{ message }}</p><p v-if="error" class="form-error" role="alert">{{ error }}</p><div class="form-actions"><button class="primary-button" type="submit" :disabled="loading || saving">{{ saving ? '保存中…' : '保存配置' }}</button></div></form></section></template>
